UPDATE T_NOTICE
SUBJECT = TRIM(#{subject}), CONTENT = #{content}, ATTACHED_FILE_FLAG = TRIM(#{attachedFileFlag}), TARGET_USER = TRIM(#{targetUser}), USE_YN = TRIM(#{useYn}), START_DATE = TRIM(#{startDate}), END_DATE = TRIM(#{endDate}),
WHERE TRIM(CAT_CD) = TRIM(#{catCd}) AND SEQ_NO = #{seqNo}
